        lo, hi = min(r for r, _ in cells), max(r for r, _ in cells)
        shift = (wi + 1 - lo) if below else (wi - 1 - hi)
        shifted = [(r + shift, c) for r, c in cells]
        # Restore the area vacated by the moving object to background.
        for r, c in cells:
